use customer_behavior;
select * from customer;


-- 1. Revenue Analyis --
-- Compare total revenue generated by male and female customers--

select gender, sum(purchase_amount) as total_revenue
 from customer
group by gender;


-- 2. Discount & Spending Analysis --
-- Identified discount users whose purchase amounts were at or above the overall average

select customer_id,purchase_amount
	from customer
    where discount_applied = 'yes'
    and purchase_amount>=
(select avg(purchase_amount) from customer);


-- 3. Product Rating Analysis--
-- Ranked the top 5 products by average review rating--

select item_purchased , round(avg(review_rating),2) as "Average Product rating" from customer
	group by item_purchased 
    order by avg(review_rating)desc limit 5;
    
    
-- 4. Shipping Analysis --
-- Compare average purchase amount for standard and express shipping


select shipping_type ,  round(avg(purchase_amount),2) from customer
	where shipping_type in ( 'standard' , 'Express')
    group by shipping_type;
    
    
-- 5. Subscription Analysis --
-- Compare customer counts, average spending and total revenue between subscribers and non-subscribers.

select subscription_status,
	count(customer_id) as total_customers,
	round(avg(purchase_amount),2) as avg_spend,
	round(sum(purchase_amount),2) as total_revenue
		from customer
        group by subscription_status
        order by total_revenue , avg_spend desc;
    

-- 6. Discount Dependency Analysis --
-- Identified the top 5 products by percentage of purchases with discount applied.

select item_purchased, 
	round(
			100*sum(
					case when discount_applied = "yes" then 1
                    else 0 end) /count(*),2)
                    as discount_rate 
                    from customer group by item_purchased
                    order by discount_rate desc limit 5;


-- 7. Customer Segmentation
-- Classified customers into new, returning, and loyal segments based on previous purchases.


with customer_type as
	( select customer_id, previous_purchases,
    case when previous_purchases =1 then 'New'
		when previous_purchases between 2 and 10 then "Returning"
    else "Loyal"
    end as customer_segment
    from customer)
    select customer_segment, count(*) as number_of_customers
    from customer_type 
    group by customer_segment;
    
    
    
-- 8. Product Popularity Analysis --
-- Identified the top 3 most purchased products within eah category


with item_counts as 
	( select category, item_purchased,
    count(customer_id) as total_orders,
    row_number() over(partition by category order by count(customer_id) desc ) as item_rank
    from customer 
    group by category,item_purchased)
select item_rank, category,item_purchased,total_orders
from item_counts where item_rank <=3; 
    

-- 9. Repeat Buyer Analysis --
-- compared subscription status among customers with more than 5 previous purchases.

select subscription_status , count(customer_id) as repeated_buyers
from customer where previous_purchases >5
group by subscription_status;


-- 10. Age Group Revenue Analysis --
-- Compared total revenue across customer age group.

select age_group , sum(purchase_amount) as total_revenue from customer
group by age_group order by total_revenue desc;
    
    
    